    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Precompute the hash of the needle
    hash_n = 0
    for c in needle:
        hash_n = (hash_n * 256 + ord(c)) % 10**9 + 7

    # Precompute the hash of the first window in haystack
    hash_h = 0
    for i in range(len_n):
        hash_h = (hash_h * 256 + ord(haystack[i])) % 10**9 + 7

    base = 256
    mod = 10**9 + 7

    for i in range(len_h - len_n + 1):
        if hash_h == hash_n:
            # Verify by comparing characters directly
            match = True
            for j in range(len_n):
                if haystack[i + j] != needle[j]:
                    match = False
                    break
            if match:
                return i
        # Update rolling hash for next window
        if i < len_h - len_n:
            hash_h = (hash_h - ord(haystack[i]) * (base ** (len_n - 1)) % mod) % mod
            hash_h = (hash_h * base + ord(haystack[i + len_n])) % mod

    return -1
