def solve(n, prerequisites):
    # Build adjacency list and in-degree count
    graph = [[] for _ in range(n)]
    in_degree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    # Stack for DFS
    stack = []
    visited = [False] * n

    def dfs(node):
        if visited[node]:
            return
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
        stack.append(node)

    for i in range(n):
        if not visited[i]:
            dfs(i)

    # Check if all nodes were visited
    if len(stack) != n:
        return []

    # Reverse to get topological order
    return stack[::-1]
