    points = []
    for start, end in intervals:
        points.append((start, 'start'))
        points.append((end, 'end'))

    # Sort the points by value, and by type ('start' comes before 'end' when values are equal)
    points.sort(key=lambda x: (x[0], 0 if x[1] == 'start' else 1))

    merged = []
    current_start = None
    current_end = None

    for point, typ in points:
        if typ == 'start':
            if current_start is None:
                current_start = point
            else:
                # If a new interval starts but the previous one is still active, we need to check if it overlaps
                if point <= current_end:
                    # Overlapping, extend the current interval
                    current_end = max(current_end, point)
                else:
                    # No overlap, finalize the current interval and start a new one
                    merged.append([current_start, current_end])
                    current_start = point
        else:
            if current_start is not None:
                if point >= current_end:
                    # No overlap, finalize the current interval
                    merged.append([current_start, current_end])
                    current_start = None
                    current_end = None
                else:
                    # Overlapping, extend the current interval
                    current_end = max(current_end, point)

    # Add the last interval if it exists
    if current_start is not None:
        merged.append([current_start, current_end])

    return merged
