def solve(nums, k):
    count = Counter(nums)
    frequencies = list(count.values())
    max_freq = max(frequencies)
    current = max_freq
    result = []
    for num, freq in count.items():
        if current == freq:
            result.append(num)
        elif current > freq:
            current = freq
            result = [num]
        else:
            continue
        if len(result) == k:
            break
    return result
