def solve(nums, k):
    frequency = defaultdict(int)
    for num in nums:
        frequency[num] += 1

    # Use a heap to keep track of the top k elements based on frequency
    # We store tuples of (-frequency, num) to simulate a max-heap
    heap = []
    for num, count in frequency.items():
        if len(heap) < k:
            heapq.heappush(heap, (-count, num))
        else:
            # If the current frequency is higher than the smallest frequency in the heap
            if count > -heap[0][0]:
                heapq.heappop(heap)
                heapq.heappush(heap, (-count, num))

    # Extract the elements from the heap
    result = []
    while heap:
        result.append(heapq.heappop(heap)[1])

    return result
